module bulk_stream_sink #(parameter DATA_WIDTH=64)(input clk,input rst_n,input valid,output ready,input [DATA_WIDTH-1:0] data,input frame_start,input frame_end,input [63:0] timestamp,input [7:0] source_id,output reg [31:0] frame_count,output reg [31:0] sample_count); reg in_frame; assign ready=1'b1; always @(posedge clk or negedge rst_n) if(!rst_n) begin in_frame<=0;frame_count<=0;sample_count<=0; end else if(valid&&ready) begin if(frame_start) begin if(in_frame)$error("nested frame"); in_frame<=1;frame_count<=frame_count+1'b1; end else if(!in_frame)$error("sample outside frame"); sample_count<=sample_count+1'b1; if(frame_end) in_frame<=0; $display("[BULK] source=%0d timestamp=%0d data=%h",source_id,timestamp,data); end endmodule
